import warp as wpimport numpy as npfrom . import smooth_posfrom .types import Datafrom .types import JointTypefrom .types import Modelfrom .warp_util import event_scopewp.set_module_options({"enable_backward": False})# copy from support.jac but for numpy arraysdef jac(        # Model:        body_parentid: np.array,        body_rootid: np.array,        dof_bodyid: np.array,        # Data in:        subtree_com_in: np.array,        cdof_in: np.array,        # In:        point: np.array,        bodyid: int,        dofid: int,):    dof_bodyid_ = dof_bodyid[dofid]    in_tree = int(dof_bodyid_ == 0)    parentid = bodyid    while parentid != 0:        if parentid == dof_bodyid_:            in_tree = 1            break        parentid = body_parentid[parentid]    if not in_tree:        return wp.vec3(0.0), wp.vec3(0.0)    offset = point - subtree_com_in[body_rootid[bodyid]]    cdof = cdof_in[dofid]    cdof_ang = cdof[0:3]    cdof_lin = cdof[3:6]    jacp = cdof_lin + np.cross(cdof_ang, offset)    jacr = cdof_ang    return jacp, jacr@event_scopedef _model_init(m: Model, d: Data):    smooth_pos.kinematics(m, d)    smooth_pos.com_pos(m, d)    smooth_pos.muscle_path_length(m, d)    smooth_pos.crb(m, d)    M = d.qM.numpy()[0]    M_inv = np.linalg.inv(M)    # 1. Compute mean inertia    m.mean_inertia = np.trace(M) / m.nv    # 2. Body inv weight    body_parentid = m.body_parentid.numpy()    body_rootid = m.body_rootid.numpy()    body_num_dofs = m.jnt_dofnum.numpy()    body_dof_adr = m.jnt_dofadr.numpy()    body_jnt_type = m.jnt_type.numpy()    dof_bodyid = m.dof_bodyid.numpy()    subtree_com_in = d.subtree_com.numpy()[0]    cdof_in: np.array = d.cdof.numpy()[0]    body_pos = d.xipos.numpy()[0]    body_inv_weights = []    for i in range(m.nbody):        body_mass_com = body_pos[i]        body_J = np.zeros((6, m.nv), dtype=np.float32)        for j in range(m.nv):            jac_p, jac_r = jac(body_parentid, body_rootid, dof_bodyid,                    subtree_com_in, cdof_in,                    body_mass_com, i, j)            body_J[0:3, j] = jac_p            body_J[3:6, j] = jac_r        # Compute J * M_inv * J^T        J_Minv_JT = body_J @ M_inv @ body_J.T        J_Minv_JT_diag = np.diagonal(J_Minv_JT)        inv_weight_trans = J_Minv_JT_diag[0:3].mean()        inv_weight_rot = J_Minv_JT_diag[3:6].mean()        body_inv_weights.append([inv_weight_trans, inv_weight_rot])    assert len(body_inv_weights) == m.nbody    m.body_invweight0 = wp.array(body_inv_weights, dtype=wp.vec2)    # 3. dof inv weight    M_inv_diag = M_inv.diagonal()    inv_weights = []    for i in range(m.nbody):        jnt_type = body_jnt_type[i]        dof_start = body_dof_adr[i]        if jnt_type == JointType.FREE:            ind_trans = np.arange(dof_start, dof_start + 3)            ind_rot = np.arange(dof_start + 3, dof_start + 6)            inv_weight_trans = M_inv_diag[ind_trans].mean()            inv_weight_rot = M_inv_diag[ind_rot].mean()            inv_weights += [inv_weight_trans] * 3 + [inv_weight_rot] * 3        elif jnt_type == JointType.BALL:            ind_rot = np.arange(dof_start, dof_start + 3)            inv_weight_rot = M_inv_diag[ind_rot].mean()            inv_weights += [inv_weight_rot] * 3        else:            num_dofs = body_num_dofs[i]            for j in range(num_dofs):                ind = dof_start + j                inv_weight = M_inv_diag[ind]                inv_weights.append(inv_weight)    assert len(inv_weights) == m.nv    m.dof_invweight0 = wp.array(inv_weights, dtype=wp.float32)    return